INSERT INTO `concept` VALUES (1,'вещь','вещь — предмет; object of: разрушение. Species: information object, артефакт, деталь, организм, помещение, природный объект',0,0,1,0,0,1,0,NULL,1,1,1),(2,'цвет','цвет — визуальное; object of: зрение. Species: бежевый, белый, бирюзовый, бордовый, желтый, зеленый, золотой, коричневый, красный, оранжевый, розовый, серебряный, серый, синий, фиолетовый, черный',0,0,0,0,0,0,1,NULL,1,1,1),(3,'синий','синий — цвет; opposite: красный; opposite: зеленый; opposite: желтый; opposite: черный; opposite: белый',0,0,0,0,0,0,1,NULL,1,1,1),(4,'красный','красный — цвет; opposite: зеленый; opposite: желтый; opposite: черный; opposite: белый; opposite: синий',0,0,0,0,0,0,1,NULL,1,1,1),(5,'визуальное','визуальное — сенсорное. Species: мутный, полосатый, прозрачный, светлый, тусклый, тёмный, цвет, яркий',0,0,0,0,0,0,1,NULL,1,1,1),(6,'сенсорное','сенсорное — свойство; object of: восприятие. Species: визуальное, вкус, запах, звук, тактильное качество',0,0,0,0,0,0,1,NULL,1,1,1),(7,'мебель','мебель — артефакт; made of: древесина (90%). Species: буфет, вешалка, детский стул, диван, зеркало, комод, кресло, кровать, письменный стол, полка, стол, стул, табурет, тумбочка, шкаф, этажерка',0,0,0,1,0,1,0,NULL,1,1,1),(8,'стол','стол — мебель; inherent: столешница (95%); inherent: ножка (95%); made of: металл (40%); coordinate with: стул',0,0,1,0,0,1,0,NULL,1,1,1),(9,'материал','материал — вещество. Species: асфальт, бетон, бумага, древесина, картон, керамика, кирпич, клей, кожа, краска, лак, мех, пластик, резина, смола, солома, стекло, ткань, цемент',0,0,0,0,0,1,0,NULL,1,1,1),(10,'деревянное','деревянное — физическое свойство; coordinate with: железо',0,0,0,0,0,0,1,NULL,1,1,1),(11,'зеленый','зеленый — цвет; opposite: желтый; opposite: черный; opposite: белый; opposite: синий; opposite: красный',0,0,0,0,0,0,1,NULL,1,1,1),(12,'желтый','желтый — цвет; opposite: черный; opposite: белый; opposite: синий; opposite: красный; opposite: зеленый',0,0,0,0,0,0,1,NULL,1,1,1)